<node TEXT="uvm_object_wrapper" POSITION="bottom_or_right" ID="ID_1186376808" CREATED="1673718059296" MODIFIED="1724664357541" BACKGROUND_COLOR="#cccccc"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      File: uvm_factory.svh
    </p>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#569cd6">virtual</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;uvm_object</font><font color="#cccccc">&nbsp; </font><font color="#dcdcaa">create_object</font><font color="#cccccc">&nbsp;(</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;name</font><font color="#d4d4d4">=</font><font color="#ce9178">&quot;&quot;</font><font color="#cccccc">);</font>
      </div>
    </div>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#569cd6">virtual</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;uvm_component</font><font color="#cccccc">&nbsp; </font><font color="#dcdcaa">create_component</font><font color="#cccccc">&nbsp;(</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;&nbsp;name,</font><font color="#569cd6">uvm_component</font><font color="#cccccc">&nbsp;parent);</font>
      </div>
    </div>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#c586c0">pure</font><font color="#cccccc">&nbsp;</font><font color="#569cd6">virtual</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;&nbsp;string</font><font color="#cccccc">&nbsp;</font><font color="#dcdcaa">get_type_name</font><font color="#cccccc">(); </font>

        <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
          <div>
            <font color="#569cd6">virtual</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;void</font><font color="#cccccc">&nbsp; </font><font color="#dcdcaa">initialize</font><font color="#cccccc">();</font>
          </div>
        </div>
      </div>
    </div>
    <p>
      
    </p>
    <p>
      <b>Helper Classes: </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. uvm_registry_common </b>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>2. uvm_registry_component_creator </b>
    </p>
    <p>
      
    </p>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#c586c0">virtual class</font><font color="#cccccc">&nbsp;</font><font color="#4ec9b0">uvm_registry_component_creator</font><font color="#cccccc">; </font>
      </div>
    </div>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#c586c0">&nbsp;static</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;uvm_component</font><font color="#cccccc">&nbsp;</font><font color="#dcdcaa">create_by_type(</font><font color="#569cd6">uvm_object_wrapper</font><font color="#cccccc">&nbsp;obj_wrpr,</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;contxt,</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;name,</font><font color="#569cd6">uvm_component</font><font color="#cccccc">&nbsp;parent); </font>

        <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
          <div>
            <font color="#c586c0">&nbsp;&nbsp;return</font><font color="#cccccc">&nbsp;factory.</font><font color="#dcdcaa">create_component_by_type</font><font color="#cccccc">( obj_wrpr, contxt, name, parent ); &nbsp;</font><font color="#c586c0">endfunction </font>

            <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
              <div>
                <font color="#c586c0">&nbsp;static</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;string</font><font color="#cccccc">&nbsp;</font><font color="#dcdcaa">base_type_name</font><font color="#cccccc">(); &nbsp;</font><font color="#c586c0">return</font><font color="#cccccc">&nbsp;</font><font color="#ce9178">&quot;component&quot;</font><font color="#cccccc">; &nbsp;</font><font color="#c586c0">endfunction </font>
              </div>
              <div>
                <font color="#c586c0">endclass</font>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>3. uvm_registry_object_creator </b>
    </p>
    <p>
      
    </p>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#c586c0">virtual class</font><font color="#cccccc">&nbsp;</font><font color="#4ec9b0">uvm_registry_object_creator</font><font color="#cccccc">; </font>
      </div>
    </div>
    <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
      <div>
        <font color="#c586c0">&nbsp;static</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;&nbsp;uvm_component</font><font color="#cccccc">&nbsp;</font><font color="#dcdcaa">create_by_type(</font><font color="#569cd6">uvm_object_wrapper</font><font color="#cccccc">&nbsp;&nbsp;obj_wrpr,</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;contxt,</font><font color="#569cd6">string</font><font color="#cccccc">&nbsp;&nbsp;name,</font><font color="#569cd6">uvm_object</font><font color="#cccccc">&nbsp;unused); </font>

        <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
          <div>
            <font color="#c586c0">&nbsp;&nbsp;return</font><font color="#cccccc">&nbsp;factory.</font><font color="#dcdcaa">create_object_by_type</font><font color="#cccccc">( obj_wrpr, contxt, name); &nbsp;</font><font color="#c586c0">endfunction </font>

            <div style="color: #cccccc; background-color: #1f1f1f; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 18px; line-height: 24px; white-space: pre">
              <div>
                <font color="#c586c0">&nbsp;static</font><font color="#cccccc">&nbsp;</font><font color="#c586c0">function</font><font color="#569cd6">&nbsp;&nbsp;string</font><font color="#cccccc">&nbsp;</font><font color="#dcdcaa">base_type_name</font><font color="#cccccc">(); &nbsp;</font><font color="#c586c0">return</font><font color="#cccccc">&nbsp; </font><font color="#ce9178">&quot;object&quot;</font><font color="#cccccc">; &nbsp;</font><font color="#c586c0">endfunction </font>
              </div>
              <div>
                <font color="#c586c0">endclass</font>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </body>
</html></richcontent>
